class Solution:
    def countPrefixes(self, words: List[str], s: str) -> int:
        ans = 0
        for w in words:
            if len(w) <= len(s) and all(w[j] == s[j] for j in range(len(w))):
                ans += 1
        return ans

c.cpp:
class Solution {
public:
    int countPrefixes(vector<string>& words, string s) {
        int ans = 0;
        for (auto& w : words) {
            bool ok = w.size() <= s.size();
            for (int j = 0; ok && j < (int)w.size(); ++j)
                if (w[j] != s[j]) ok = false;
            ans += ok;
        }
        return ans;
    }
};

c.java:
class Solution {
    public int countPrefixes(String[] words, String s) {
        int ans = 0;
        for (String w : words) {
            boolean ok = w.length() <= s.length();
            for (int j = 0; ok && j < w.length(); j++)
                if (w.charAt(j) != s.charAt(j)) ok = false;
            if (ok) ans++;
        }
        return ans;
    }
}

